  "gdprCenter.contact.privacy": "privacy@realaicoach.app",
  "gdprCenter.contact.request": "Flusso di lavoro per richiesta di privacy verificata per esportazione o cancellazione",
  "gdprCenter.contact.title": "Domande GDPR, opposizioni o escalation autoritaria",
  "gdprCenter.fact.lawful.body": "Il contratto, l'interesse legittimo, il consenso e l'obbligo legale si applicano a seconda del flusso di lavoro.",
  "gdprCenter.fact.lawful.title": "Base legale",
